Let $p, h_1,\dots, h_l \in \Real{}[x]$ be real-valued multivariate polynomials in $x \in \Real{d}$, we consider the following equality constrained polynomial optimization problem\footnote{Although our framework can be generalized to problems with inequality constraints, here we focus on equality constraints to simplify the presentation.}
\begin{equation} \label{eq:pop}
\min_{x \in \Real{d}} \cbrace{p(x)\ |\ h_i(x)=0, i=1,\dots,l}. \tag{POP}
\end{equation}

{\bf SDP Relaxations for Polynomial Optimization Problems}. Towards this goal, let us first give an overview of the celebrated Lasserre's moment/sums-of-squares (SOS) semidefinite relaxation hierarchy~\cite{Lasserre01siopt-LasserreHierarchy,Parrilo03MP-SOS}. Let $\kappa \geq 1$ be an integer such that $2\kappa$ is equal or greater than the maximum degree of $p,h_i,i=1,\dots,l$, and denote 


$v := [x]_\kappa$ as the standard vector of monomials in $x$ of degree up to $\kappa$. We build the \emph{moment matrix} $X := [x]_\kappa [x]_\kappa\tran$ that contains the standard monomials in $x$ of degree up to $2\kappa$. 
As a result,
$p$ and $h_i$'s can be written as linear functions in $X$.


\begin{equation}\label{eq:primalSDP}
\min_{X \in \sym{n}} \cbrace{\inprod{C}{X}\ |\ \calA(X) = b, \ X \succeq 0},\tag{P}
\end{equation}

where $n := \bard_\kappa \triangleq \nchoosek{d+\kappa}{\kappa}$ is the dimension of $[x]_\kappa$, $b \in \Real{m}$, $\calA: \sym{n} \rightarrow \Real{m}$ is a linear map $\calA(X) \triangleq (\inprod{A_i}{X})_{i=1}^m$ with $A_i \in \sym{n}$, that is onto and collects all independent linear constraints generated by the relaxation \blue{of $X =[x]_\kappa [x]_\kappa\tran$ to $X \succeq 0$}. Let $\calAadj: \Real{m} \rightarrow \sym{n}$ be the adjoint of $\calA$ defined as $\calAadj y \triangleq \sum_{i=1}^m y_i A_i$, then the Lagrangian dual of problem~\eqref{eq:primalSDP} reads
\begin{equation}\label{eq:dualSDP}
\max_{y \in \Real{m}, S \in \sym{n}} \cbrace{\inprod{b}{y}\ |\ \calAadj y + S = C,\ S \succeq 0},\tag{D}
\end{equation}

Throughout this paper, we assume that strong duality holds for \eqref{eq:primalSDP} and \eqref{eq:dualSDP}, and both \eqref{eq:primalSDP} and \eqref{eq:dualSDP} admit at least one solution.\footnote{Particularly, if a redundant ball constraint is included in the relaxation, then dual Slater and strong duality hold for Lasserre's moment relaxations of all orders \cite[Theorem 1]{Josz16OL-strongdualityLasserre}.}  We denote $\Xstar$ and $(\ystar,\Sstar)$ as an optimal solution for \eqref{eq:primalSDP} and \eqref{eq:dualSDP}, respectively. Then, the KKT condition for \eqref{eq:primalSDP} and \eqref{eq:dualSDP} given as


\begin{equation}
	\label{eq-kkt-sdp}
		\cA(X) - b = 0,\quad \cA^*y + S - C = 0,\quad \inprod{X}{S} = 0,\quad X, S\succeq 0,	
	\end{equation}

	has $(\Xstar,\ystar,\Sstar)$ as one of its solutions. Moreover, it follows that $\fpopstar \geq \fpsdpstar = \fdsdpstar$, where $\fpsdpstar$ and $\fdsdpstar$ are the optimal values of~\eqref{eq:primalSDP} and~\eqref{eq:dualSDP}, respectively. The SDP relaxation is said to be \emph{tight} if $\fpopstar = \fpsdpstar$. In such cases, for any global minimizer $\xstar$ of \eqref{eq:pop}, the rank one lifting $X = [\xstar]_\kappa [\xstar]_\kappa\tran$ is a minimizer of~\eqref{eq:primalSDP}, 
	{and any rank one optimal solution  $\Xstar$ of \eqref{eq:primalSDP} corresponds to a global minimizer of \eqref{eq:pop}.}


We use $\mathcal{X}$ and $\mathcal{Y}$ to denote finite dimensional Euclidean spaces. Let $\sym{n}$ be the space of real symmetric $n\times n$ matrices, and $\psd{n}$ (resp. $\pd{n}$) be the set of positive semidefinite (resp. definite) matrices. We also write $X \succeq 0$ (resp. $X \succ 0$) to indicate that $X$ is positive semidefinite (resp. definite) when the dimension of $X$ is clear. We use $\usphere{d-1}:=\{ x \in \Real{d}\mid \norm{x} = 1 \}$ to denote the $d$-dimensional unit sphere. For $x \in \Real{n}$, $\norm{x} = \sqrt{x\tran x}$ is the standard $\ell_2$ norm. For $X \in \Real{m \times n}$, $\norm{X} = \sqrt{\trace{X\tran X}}$ denotes the Frobenius norm. $\norm{x}_{\calH} := \sqrt{\inprod{x}{\calH x}}$ denotes the $\calH$-weighted norm for a positive semidefinite mapping $\calH$.


\begin{equation*}
	\mathcal{F}_{\mathrm{P}} := \left\{ X\in \mathbb{S}^n\;\middle |\; \mathcal{A}(X) = b,\; X\in \mathbb{S}_+^n\right\},
\end{equation*}

\begin{algorithm}
	\caption{An inexact projected gradient method (\ipgm) for SDP \eqref{eq:primalSDP}.}
	\label{alg-iPGM}
	\begin{algorithmic}
		\item[{\bf Input}:] Initial points $(X^0, y^0, S^0)\in \mathbb{S}^n_+ \times \mathbb{R}^m \times \mathbb{S}^n_+$, a nondecreasing positive sequence $\{\sigma_k\}$ and a nonnegative sequence $\{\varepsilon_k\}$ such that $\{k\epsilon_k\}$ is summable.
		\item[{\bf Repeat} For $k \geq 1$:] 
		\item[\quad] Compute 
		\begin{equation}
		\label{eq-iPGM-proj}	
		X^{k} \approx \Pi_{\mathcal{F}_{\mathrm{P}}}\left(X^{k-1} - \sigma_k C\right),\quad X^{k} \in \mathbb{S}_+^n
		\end{equation}
		with associated dual pair $(y^{k}, S^{k})\in \mathbb{R}^m\times \mathbb{S}_+^n$ such that the following conditions hold:
		\begin{equation}
		\label{eq-iPGM-inexact-conditions}
		\begin{aligned}
			\norm{\mathcal{A}(X^{k}) - b} \leq &\; \varepsilon_k, \\
				\mathcal{A}^*y^k + S^k - C - \frac{1}{\sigma_k}\left(X^{k} - X^{k-1}\right)= &\; 0, \\
				\inprod{X^{k}}{S^{k}} = &\;0.
			\end{aligned}
		\end{equation}
		\item[{\bf Until}:] Termination conditions are met (\cf Section \ref{sec:numexps}).
		\item[{\bf Output}:] $(X^k,y^k,S^k)$.
	\end{algorithmic}
\end{algorithm}

	\item\label{item:rounding} {\bf (Rounding)}. Let $\barX^{k} = \sum_{i=1}^n \lambda_i v_i v_i\tran$ be the spectral decomposition of $\barX^{k}$ with $\lambda_1 \geq \dots \geq \lambda_n$ in nonincreasing order. Compute $r \geq 1$ hypotheses for the \eqref{eq:pop} from the leading $r$ eigenvectors $v_1,\dots, v_r$   
	\bea
		\bar{x}^{k}_{i} = \rounding(v_i), \quad i = 1,\dots,r,
	\eea
	where the function~\rounding~can be problem-dependent and we provide examples in the numerical experiments in Section~\ref{sec:numexps}. Generally, if the SDP~\eqref{eq:primalSDP} comes from a dense relaxation, and the feasible set of the original~\eqref{eq:pop}, denoted as $\setpop$, is simple to project, then we can design~\rounding~to be
	\bea
	v_i \leftarrow \frac{v_i}{v_i[1]}, \quad \bar{x}^{k}_{i} \leftarrow \Pi_{\setpop}(v_i[x]),
	\eea
	where one first normalizes $v_i$ such that its leading entry $v_i[1]$ is equal to $1$, and then projects its entries corresponding to order-one monomials,~\ie~$v_i[x]$, to the feasible set of~\eqref{eq:pop}. Note that the rationale for designing this rounding method is that practical POP applications often involve simple constraints such as binary~\cite{Goemans95JACM-maxcut}, unit sphere~\cite{Yang19ICCV-wahba}, and orthogonality~\cite{Yang20neurips-onering,Briales17CVPR-3Dregistration}, whose projection maps are simple (\eg if $x$ is binary, then $\Pi_{\setpop}(v_i[x]) = \sign\parentheses{v_i[x]}$ just takes the sign of each entry of $v_i[x]$). If $\setpop$ is not easy to project, then we omit the projection, in which case the local search will start from an infeasible initialization.
	\item {\bf (Local Search)}. Apply a local search method for the POP (as an NLP) with the initial point chosen as $ \bar{x}^{k}_i $ for each hypothesis $i=1,\dots,r$. Denote the solution of each local search as $ \hat{x}^{k}_i $, with associated objective value $p(\hatx^{k}_i)$, choose the best local solution with minimum objective value. Formally, we have
	\bea
	\hatx_i^{k} = \nlp(\barx^{k}_i),\quad i=1,\dots,r, \quad \hatx^{k} = \argmin_{\hatx^{k}_i, i=1\dots,r} p(\hatx^{k}_i).
	\eea

	\item\label{item:lifting} {\bf (Lifting)}. Perform a rank-one lifting of the best local solution according to the SDP relaxation scheme
	\bea
	\hatX^{k} = v\parentheses{\hatx^{k}} v\parentheses{\hatx^{k}}\tran,
	\eea
	where $v: \Real{d} \rightarrow \Real{n}$ is a dense or sparse monomial lifting (\eg $v(x) = [x]_\kappa$ is the full set of monomials up to degree $\kappa$ in the case of dense Lasserre's hierarchy at order $\kappa$).


\begin{algorithm}
	\caption{An inexact projected gradient method accelerated \blue{via rounding and lifting by} NLP for solving tight SDP relaxations of POPs (\name).}
	\label{alg-iPGMnlp}
	\begin{algorithmic}
		\item[{\bf Input}:] Initial points $ (X^{0}, y^0, S^0)\in \mathbb{S}_+^n\times \mathbb{R}^{m}\times\mathbb{S}_+^n $, a nondecreasing positive sequences $ \{\sigma_k\}$, a nonnegative sequence $\{\varepsilon_k\}$ such that $\{k\varepsilon_k\}$ is summable, a stopping criterion $\eta:\mathbb{S}^n_+\times \mathbb{R}^m\times \mathbb{S}_+^n\rightarrow \mathbb{R}_+$ with a tolerance $ {\tt Tol} > 0 $. Initialize $\calV = \{ X^0 \}$ if $X^0\in \setsdpp$ and $\calV = \emptyset$ otherwise. Choose a positive integer $r \in [1,n]$, and a positive constant $\epsilon>0$. 
		\item[{\bf Iterate} the following steps for $ k = 1,\dots $:]
		\item[\quad {\bf Step 1 (Projection)}.] Compute $(\overline{X}^k, y^k, S^{k})$ satisfying \eqref{eq-iPGM-proj} and \eqref{eq-iPGM-inexact-conditions} (see Section \ref{sec:apgsubproblem}).
		\item[\quad {\bf Step 2 (Certification)}.] If $ \eta(\barX^{k}, y^{k}, S^{k}) < {\tt Tol} $, {\bf output} $(\barX^{k}, y^{k}, S^{k})$ and {\bf stop}.
		\item[\quad {\bf Step 3 (Acceleration)}.] Compute $ \widehat{X}^{k} $ as in items~\ref{item:rounding}-\ref{item:lifting}:
		\bea
			& \barX^{k} = \sum_{i=1}^n \lambda_i v_i v_i\tran, \quad \bar{x}^{k}_{i} = \rounding(v_i), \quad i = 1,\dots,r, \nonumber \\
			& \hatx_i^{k} = \nlp(\barx^{k}_i), \quad i=1,\dots,r, \quad \hatx^{k} = \argmin_{\hatx^{k}_i, i=1\dots,r} p(\hatx^{k}_i), \nonumber \\
			& \hatX^{k} = v\parentheses{\hatx^{k}} v\parentheses{\hatx^{k}}\tran. \nonumber 
		\eea
		\item[\quad {\bf Step 4 (Policy)}.] Update $X^{k}$ according to 
		\begin{equation}
			\label{eq:accept-reject}
			X^{k} = 
				\begin{cases}
					\hatX^{k} & {\rm if }\; \inprod{C}{\hatX^k} < 
					\blue{\min \left(\inprod{C}{\barX^k}, \min_{X\in \calV} \left\{\inprod{C}{X}\;\middle|\; X\in \calV\right\}\right)} - \epsilon,\; \widehat{X}^{k} \in \setsdpp  \\
					\barX^{k} & {\rm otherwise }
				\end{cases}.
		\end{equation}
		If $X^{k} = \hatX^{k}$, set $\calV \leftarrow \calV \cup \{ \hatX^k \}$.
	\end{algorithmic}
\end{algorithm}

