Let $p, h_1,\dots, h_l \in \Real{}[x]$ be real-valued multivariate polynomials in $x \in \Real{d}$, we consider the following equality constrained polynomial optimization problem\footnote{Although our framework can be generalized to problems with inequality constraints, here we focus on equality constraints to simplify the presentation.}
\begin{equation} \label{eq:pop}
\min_{x \in \Real{d}} \cbrace{p(x)\ |\ h_i(x)=0, i=1,\dots,l}. \tag{POP}
\end{equation}

\begin{equation}\label{eq:primalSDP}
\min_{X \in \sym{n}} \cbrace{\inprod{C}{X}\ |\ \calA(X) = b, \ X \succeq 0},\tag{P}
\end{equation}

where $n := \bard_\kappa \triangleq \nchoosek{d+\kappa}{\kappa}$ is the dimension of $[x]_\kappa$, $b \in \Real{m}$, $\calA: \sym{n} \rightarrow \Real{m}$ is a linear map $\calA(X) \triangleq (\inprod{A_i}{X})_{i=1}^m$ with $A_i \in \sym{n}$, that is onto and collects all independent linear constraints generated by the relaxation \blue{of $X =[x]_\kappa [x]_\kappa\tran$ to $X \succeq 0$}. Let $\calAadj: \Real{m} \rightarrow \sym{n}$ be the adjoint of $\calA$ defined as $\calAadj y \triangleq \sum_{i=1}^m y_i A_i$, then the Lagrangian dual of problem~\eqref{eq:primalSDP} reads
\begin{equation}\label{eq:dualSDP}
\max_{y \in \Real{m}, S \in \sym{n}} \cbrace{\inprod{b}{y}\ |\ \calAadj y + S = C,\ S \succeq 0},\tag{D}
\end{equation}

\begin{equation}
	\label{eq-kkt-sdp}
		\cA(X) - b = 0,\quad \cA^*y + S - C = 0,\quad \inprod{X}{S} = 0,\quad X, S\succeq 0,	
	\end{equation}

\begin{equation*}
	\mathcal{F}_{\mathrm{P}} := \left\{ X\in \mathbb{S}^n\;\middle |\; \mathcal{A}(X) = b,\; X\in \mathbb{S}_+^n\right\},
\end{equation*}

\begin{algorithm}
	\caption{An inexact projected gradient method (\ipgm) for SDP \eqref{eq:primalSDP}.}
	\label{alg-iPGM}
	\begin{algorithmic}
		\item[{\bf Input}:] Initial points $(X^0, y^0, S^0)\in \mathbb{S}^n_+ \times \mathbb{R}^m \times \mathbb{S}^n_+$, a nondecreasing positive sequence $\{\sigma_k\}$ and a nonnegative sequence $\{\varepsilon_k\}$ such that $\{k\epsilon_k\}$ is summable.
		\item[{\bf Repeat} For $k \geq 1$:] 
		\item[\quad] Compute 
		\begin{equation}
		\label{eq-iPGM-proj}	
		X^{k} \approx \Pi_{\mathcal{F}_{\mathrm{P}}}\left(X^{k-1} - \sigma_k C\right),\quad X^{k} \in \mathbb{S}_+^n
		\end{equation}
		with associated dual pair $(y^{k}, S^{k})\in \mathbb{R}^m\times \mathbb{S}_+^n$ such that the following conditions hold:
		\begin{equation}
		\label{eq-iPGM-inexact-conditions}
		\begin{aligned}
			\norm{\mathcal{A}(X^{k}) - b} \leq &\; \varepsilon_k, \\
				\mathcal{A}^*y^k + S^k - C - \frac{1}{\sigma_k}\left(X^{k} - X^{k-1}\right)= &\; 0, \\
				\inprod{X^{k}}{S^{k}} = &\;0.
			\end{aligned}
		\end{equation}
		\item[{\bf Until}:] Termination conditions are met (\cf Section \ref{sec:numexps}).
		\item[{\bf Output}:] $(X^k,y^k,S^k)$.
	\end{algorithmic}
\end{algorithm}

\begin{algorithm}
	\caption{An inexact projected gradient method accelerated \blue{via rounding and lifting by} NLP for solving tight SDP relaxations of POPs (\name).}
	\label{alg-iPGMnlp}
	\begin{algorithmic}
		\item[{\bf Input}:] Initial points $ (X^{0}, y^0, S^0)\in \mathbb{S}_+^n\times \mathbb{R}^{m}\times\mathbb{S}_+^n $, a nondecreasing positive sequences $ \{\sigma_k\}$, a nonnegative sequence $\{\varepsilon_k\}$ such that $\{k\varepsilon_k\}$ is summable, a stopping criterion $\eta:\mathbb{S}^n_+\times \mathbb{R}^m\times \mathbb{S}_+^n\rightarrow \mathbb{R}_+$ with a tolerance $ {\tt Tol} > 0 $. Initialize $\calV = \{ X^0 \}$ if $X^0\in \setsdpp$ and $\calV = \emptyset$ otherwise. Choose a positive integer $r \in [1,n]$, and a positive constant $\epsilon>0$. 
		\item[{\bf Iterate} the following steps for $ k = 1,\dots $:]
		\item[\quad {\bf Step 1 (Projection)}.] Compute $(\overline{X}^k, y^k, S^{k})$ satisfying \eqref{eq-iPGM-proj} and \eqref{eq-iPGM-inexact-conditions} (see Section \ref{sec:apgsubproblem}).
		\item[\quad {\bf Step 2 (Certification)}.] If $ \eta(\barX^{k}, y^{k}, S^{k}) < {\tt Tol} $, {\bf output} $(\barX^{k}, y^{k}, S^{k})$ and {\bf stop}.
		\item[\quad {\bf Step 3 (Acceleration)}.] Compute $ \widehat{X}^{k} $ as in items~\ref{item:rounding}-\ref{item:lifting}:
		\bea
			& \barX^{k} = \sum_{i=1}^n \lambda_i v_i v_i\tran, \quad \bar{x}^{k}_{i} = \rounding(v_i), \quad i = 1,\dots,r, \nonumber \\
			& \hatx_i^{k} = \nlp(\barx^{k}_i), \quad i=1,\dots,r, \quad \hatx^{k} = \argmin_{\hatx^{k}_i, i=1\dots,r} p(\hatx^{k}_i), \nonumber \\
			& \hatX^{k} = v\parentheses{\hatx^{k}} v\parentheses{\hatx^{k}}\tran. \nonumber 
		\eea
		\item[\quad {\bf Step 4 (Policy)}.] Update $X^{k}$ according to 
		\begin{equation}
			\label{eq:accept-reject}
			X^{k} = 
				\begin{cases}
					\hatX^{k} & {\rm if }\; \inprod{C}{\hatX^k} < 
					\blue{\min \left(\inprod{C}{\barX^k}, \min_{X\in \calV} \left\{\inprod{C}{X}\;\middle|\; X\in \calV\right\}\right)} - \epsilon,\; \widehat{X}^{k} \in \setsdpp  \\
					\barX^{k} & {\rm otherwise }
				\end{cases}.
		\end{equation}
		If $X^{k} = \hatX^{k}$, set $\calV \leftarrow \calV \cup \{ \hatX^k \}$.
	\end{algorithmic}
\end{algorithm}

\begin{theorem}
	\label{thm-ipgmnlp}
	Let $\{(\barX^k, y^k, S^k)\}$ be any sequence generated by Algorithm \ref{alg-iPGMnlp}, and suppose that there exists a constant $M>0$ such that $\norm{y^k}\leq M$ for all $k\geq 0$. 
	% \red{Assuming Slater's conditions hold for SDP \eqref{eq:primalSDP}-\eqref{eq:dualSDP}} \blue{(LIANG: I think we do not need Slater's conditions here for global convergence, but only need them for solving subproblem. See also the red part in Page 3.)}, 
	If one chooses $\sigma_k \geq O(\sqrt{k})$ for all $k\geq 1$, then, $\left\{\inprod{C}{\barX^k}\right\}$ converges to the optimal value of the SDP problem \eqref{eq:primalSDP}. 
\end{theorem}

\begin{proof}
Let us only consider the case with $X^0 \in \setsdpp$ such that $\calV$ is initialized as $\{ X^0\}$ (the case with $\calV$ initialized as $\emptyset$ can be argued in a similar manner). By the construction of the set $\calV$, it contains a sequence of feasible points of~\eqref{eq:primalSDP}, and the objective value along this sequence is \emph{strictly} decreasing according to the acceptance policy~\eqref{eq:accept-reject}. Hence, we have the following relation:
\begin{equation*}
	\inf\left\{\inprod{C}{X}\;\middle|\; X\in \calV\right\} \leq \inprod{C}{X^0} - (|\calV|-1) \epsilon,
\end{equation*}
If $|\calV|=\infty$, then there exists an infinite sequence of feasible points to problem \eqref{eq:primalSDP} whose objective function value converges to $-\infty$. In this case, problem \eqref{eq:primalSDP} is unbounded, a contradiction (recall that we assumed strong duality throughout this paper in Section \ref{sec:introduction}). Hence, $|\calV|< \infty$. If $|\calV| = 1$, then none of the $\hatX^{k}$ generated by {\bf Step 3} has been accepted, in which case Algorithm \ref{alg-iPGMnlp} reduces to Algorithm \ref{alg-iPGM} iPGM. Therefore, by Theorem~\ref{thm-iPGM}, Algorithm \ref{alg-iPGMnlp} converges as $O(1/k)$ if one chooses $\sigma_k \geq O(\sqrt{k})$ for all $k\geq 1$. If $|\calV| > 1$, then some of the $\hatX^{k}$ generated by {\bf Step 3} have been accepted. Denote the last element of $\calV$ as $\hatX_{\calV}$ with associated dual variables $(y_\calV,S_\calV)$ (from {\bf Step 1}), then Algorithm \ref{alg-iPGMnlp} essentially reduces to \ipgm~with a new initial point at $(\hatX_{\calV}, y_\calV, S_\calV)$. Again, by Theorem~\ref{thm-iPGM}, Algorithm \ref{alg-iPGMnlp} converges as $O(1/k)$. This completes the proof.\qed
\end{proof}

Let us only consider the case with $X^0 \in \setsdpp$ such that $\calV$ is initialized as $\{ X^0\}$ (the case with $\calV$ initialized as $\emptyset$ can be argued in a similar manner). By the construction of the set $\calV$, it contains a sequence of feasible points of~\eqref{eq:primalSDP}, and the objective value along this sequence is \emph{strictly} decreasing according to the acceptance policy~\eqref{eq:accept-reject}. Hence, we have the following relation:
\begin{equation*}
	\inf\left\{\inprod{C}{X}\;\middle|\; X\in \calV\right\} \leq \inprod{C}{X^0} - (|\calV|-1) \epsilon,
\end{equation*}

\begin{theorem}
	\label{thm-iPGM}
	Let $\{(X^k, y^k, S^k)\}$ be any sequence generated by Algorithm \ref{alg-iPGM}, and suppose that there exists a constant $M>0$ such that $\norm{y^k}\leq M$ for all $k\geq 0$. Then, for all $k\geq 1$, it holds that 
	\begin{equation*}
		\left\{
			\begin{array}{l}
				\displaystyle -\frac{\norm{y^*}k\varepsilon_k}{k} \leq \inprod{C}{X^k - \Xstar} \leq \frac{1}{k}\left( \frac{1}{2\sigma_0}\norm{X^0 - \Xstar}^2 + 2M\sum_{i = 1}^k i\varepsilon_i\right), \\
				\displaystyle \norm{\mathcal{A}(X^k) - b} \leq \varepsilon_k \leq O\left(\frac{1}{k}\right), \\ 	
				\displaystyle \norm{\mathcal{A}^*y^k + S^k - C} \leq O\left( \frac{1}{\sqrt{k\sigma_k}}\right),
			\end{array}
		\right.
	\end{equation*}
	where $\Xstar$ is an optimal solution of the primal problem \eqref{eq:primalSDP} and $(\ystar, \Sstar)$ is an optimal solution of the dual problem \eqref{eq:dualSDP}. In particular, if one chooses $\sigma_k \geq O(\sqrt{k}) > 0$ for all $k\geq 1$, then we have 
	\begin{equation*}
		\max\left\{ \left\lvert \inprod{C}{X^k - \Xstar}\right\rvert, \norm{\mathcal{A}(X^k) - b}, \norm{\mathcal{A}^*y^k + S^k - C}\right\} \leq O\left(\frac{1}{k}\right).
	\end{equation*}
\end{theorem}

\begin{proof}
	For notational simplicity, denote $r^k = \mathcal{A}(X^k) - b$ and $e^k = X^k - \Xstar$ for all $k\geq 0$. Then, $\mathcal{A}(e^k) = r^k$ since $\mathcal{A}(\Xstar) = b$. Moreover, we have $\norm{r^k}\leq \varepsilon_k $ from the first condition in \eqref{eq-iPGM-inexact-conditions}. Therefore, the convergence of $\left\{\norm{r^k}\right\}$ is obvious, since $\norm{r^k}\leq \varepsilon_k$ and $\{k\varepsilon_k\}$ is summable. Recall that $\Xstar$ is an optimal solution to problem \eqref{eq:primalSDP}. Let $X = X^{k-1}$ in Lemma \ref{lemma-fk}, we get 
	\begin{equation}
	\label{eq-thm-iPGM-1}
		\inprod{C}{X^{k-1} - X^k} \geq \frac{1}{\sigma_k}\norm{e^k - e^{k-1}}^2 + \inprod{\mathcal{A}^*y^k}{e^{k-1} - e^{k}}	
	\end{equation}
	On the other hand, let $X = \Xstar$ in Lemma \ref{lemma-fk}, we obtain
	\begin{equation}
	\label{eq-thm-iPGM-2}
		\inprod{C}{\Xstar - X^k} \geq \frac{1}{\sigma_k}\norm{e^k - e^{k-1}}^2 + \frac{1}{\sigma_k}\inprod{e^{k-1}}{e^k - e^{k-1}} - \inprod{A^*y^k}{e^k}.	
	\end{equation}
	Multiplying $k-1$ to \eqref{eq-thm-iPGM-1} and add the resulting inequality to \eqref{eq-thm-iPGM-2} yields
	\begin{equation}
		\label{eq-thm-iPGM-3}
		\begin{aligned}
			&\; \inprod{C}{(k-1)\left(X^{k-1} - \Xstar \right) - k\left(X^k - \Xstar\right)  } \\ 
			\geq &\; \frac{k}{\sigma_k}\norm{e^k - e^{k-1}}^2 + \frac{1}{\sigma_k}\inprod{e^{k-1}}{e^k - e^{k-1}} + \inprod{\mathcal{A}^*y^k}{(k-1)e^{k-1} - ke^k} \\
			= &\; \frac{1}{\sigma_k}\left(k\norm{e^k}^2 + (k-1)\norm{e^{k-1}}^2 - (2k -1)\inprod{e^k}{e^{k-1}}\right) + \inprod{y^k}{(k-1)r^{k-1} - k r^k} \\
			\geq &\; \frac{1}{\sigma_k}\left(k\norm{e^k}^2 + (k-1)\norm{e^{k-1}}^2 - \frac{2k-1}{2}\left(\norm{e^k}^2 + \norm{e^{k-1}}^2\right)\right) + \inprod{y^k}{(k-1)r^{k-1} - k r^k} \\
			 = &\; \frac{1}{2\sigma_k}\norm{e^k}^2 - \frac{1}{2\sigma_k}\norm{e^{k-1}}^2 + \inprod{y^k}{(k-1)r^{k-1} - k r^k} \\
			 \geq &\; \frac{1}{2\sigma_k}\norm{e^k}^2 - \frac{1}{2\sigma_{k-1}}\norm{e^{k-1}}^2 + \inprod{y^k}{(k-1)r^{k-1} - k r^k},
		\end{aligned} 
	\end{equation}
	where in the last inequality, we use the fact that $\sigma_k \geq \sigma_{k-1} > 0$ for all $k\geq 1$. By summing the inequality in \eqref{eq-thm-iPGM-3} for $k=1,\dots,k$, we get (recall that $\norm{y^k}\leq M$ for all $k\geq 0$)
	\begin{equation*}
	\begin{aligned}
			-k \inprod{C}{X^k - \Xstar} \geq &\; \frac{1}{2\sigma_k}\norm{e^k}^2 - \frac{1}{2\sigma_0}\norm{e_0}^2 + \sum_{i=1}^k\inprod{y^i}{(i-1)r^{i-1} - i r^i} \\
			\geq &\; \frac{1}{2\sigma_k}\norm{e^k}^2 - \frac{1}{2\sigma_0}\norm{e_0}^2 - 2M\sum_{i=1}^k i\varepsilon_i.
		\end{aligned}	
	\end{equation*}
	The above inequality leads to the following upper bound on $\inprod{C}{X^k - \Xstar}$:
	\begin{equation}
	\label{eq-thm-iPGM-4}
	\inprod{C}{X^k - \Xstar} \leq \frac{1}{k}\left(\frac{1}{2\sigma_0}\norm{e^0}^2 + 2M\sum_{i=1}^k i\varepsilon_i\right).	
	\end{equation}

	Next, we shall provide a lower bound for $\inprod{C}{X^k - \Xstar}$ for $k\geq 1$. To this end, let us define the set $\mathcal{F}_k$, which is an enlargement of the primal feasible set $\mathcal{F}_{\mathrm{P}}$ with respect to $\varepsilon_k \geq 0$, as follows:
	\[
		\mathcal{F}_k:= \left\{X\in \mathbb{S}^n\; \middle | \; \norm{\mathcal{A}(X) - b}\leq \varepsilon_k,\; X\in \mathbb{S}_+^n\right\},\quad \forall\, k\geq 1. 
	\]
	Moreover, denote
	\[
		\Xstar_k:=\argmin\left\{\inprod{C}{X}\; \middle | \; X\in \mathcal{F}_k\right\},\quad \forall\, k\geq 1.
	\]
	Since $(\ystar, \Sstar)\in \mathbb{R}^m\times \mathbb{S}_+^n$ is a dual optimal solution, by \cite[Lemma 3.4]{Jiang2012}, we have that 
	\[
		0\leq \inprod{C}{\Xstar - \Xstar_k} \leq \norm{\ystar}\varepsilon_k,\quad \forall\, k\geq 1.
	\]
	As a consequence, because $X^k \in \calF_k$ and $\inprod{C}{X^k} \geq \inprod{C}{\Xstar_k}$, it holds that 
	\begin{equation}
	\label{eq-thm-iPGM-5}
		\inprod{C}{X^k - \Xstar} \geq \inprod{C}{\Xstar_k - \Xstar} \geq -\norm{\ystar}\varepsilon_k = -\frac{\norm{\ystar}k\varepsilon_k}{k}.	
	\end{equation}
	Combining \eqref{eq-thm-iPGM-4} and \eqref{eq-thm-iPGM-5}, we see that 
	\[
		-\frac{\norm{\ystar}k\varepsilon_k}{k} \leq \inprod{C}{X^k - \Xstar} \leq  \frac{1}{k}\left(\frac{1}{2\sigma_0}\norm{e^0}^2 + 2M\sum_{i=1}^k i\varepsilon_i\right).
	\]

	Finally, let us estimate the dual infeasibility. To this end, we get from \eqref{eq-thm-iPGM-1} that
	\[
		\frac{1}{\sigma_k}\norm{X^k - X^{k-1}}^2 \leq  \inprod{C}{X^{k-1} - \Xstar} - \inprod{C}{X^{k} - \Xstar} +  \norm{y^k}\left(\norm{r^{k-1}} + \norm{r^k}\right)
	\]
	which implies that 
	\[
		\begin{aligned}
			&\; \norm{\mathcal{A}^*y^k + S^k - C} =  \frac{1}{\sigma_k}\norm{X^{k} - X^{k-1}} \\
			\leq &\; \frac{1}{\sqrt{\sigma_k}}\sqrt{ \frac{1}{k-1}\left(\frac{1}{2\sigma_0}\norm{e^0}^2 + 2M\sum_{i=1}^{k-1} i\varepsilon_i\right) + \norm{\ystar}\varepsilon_k + M\left(\varepsilon_{k-1} + \varepsilon_k\right)} \\ 
			\leq &\; O\left(\frac{1}{\sqrt{k\sigma_k}}\right),
		\end{aligned} 
	\]
	and establishes the convergence of the dual infeasibility. Therefore, the proof is completed. \qed
\end{proof}

For notational simplicity, denote $r^k = \mathcal{A}(X^k) - b$ and $e^k = X^k - \Xstar$ for all $k\geq 0$. Then, $\mathcal{A}(e^k) = r^k$ since $\mathcal{A}(\Xstar) = b$. Moreover, we have $\norm{r^k}\leq \varepsilon_k $ from the first condition in \eqref{eq-iPGM-inexact-conditions}. Therefore, the convergence of $\left\{\norm{r^k}\right\}$ is obvious, since $\norm{r^k}\leq \varepsilon_k$ and $\{k\varepsilon_k\}$ is summable. Recall that $\Xstar$ is an optimal solution to problem \eqref{eq:primalSDP}. Let $X = X^{k-1}$ in Lemma \ref{lemma-fk}, we get 
\begin{equation}
\label{eq-thm-iPGM-1}
	\inprod{C}{X^{k-1} - X^k} \geq \frac{1}{\sigma_k}\norm{e^k - e^{k-1}}^2 + \inprod{\mathcal{A}^*y^k}{e^{k-1} - e^{k}}	
\end{equation}

On the other hand, let $X = \Xstar$ in Lemma \ref{lemma-fk}, we obtain
\begin{equation}
\label{eq-thm-iPGM-2}
	\inprod{C}{\Xstar - X^k} \geq \frac{1}{\sigma_k}\norm{e^k - e^{k-1}}^2 + \frac{1}{\sigma_k}\inprod{e^{k-1}}{e^k - e^{k-1}} - \inprod{A^*y^k}{e^k}.	
\end{equation}

Multiplying $k-1$ to \eqref{eq-thm-iPGM-1} and add the resulting inequality to \eqref{eq-thm-iPGM-2} yields
\begin{equation}
	\label{eq-thm-iPGM-3}
	\begin{aligned}
		&\; \inprod{C}{(k-1)\left(X^{k-1} - \Xstar \right) - k\left(X^k - \Xstar\right)  } \\ 
		\geq &\; \frac{k}{\sigma_k}\norm{e^k - e^{k-1}}^2 + \frac{1}{\sigma_k}\inprod{e^{k-1}}{e^k - e^{k-1}} + \inprod{\mathcal{A}^*y^k}{(k-1)e^{k-1} - ke^k} \\
		= &\; \frac{1}{\sigma_k}\left(k\norm{e^k}^2 + (k-1)\norm{e^{k-1}}^2 - (2k -1)\inprod{e^k}{e^{k-1}}\right) + \inprod{y^k}{(k-1)r^{k-1} - k r^k} \\
		\geq &\; \frac{1}{\sigma_k}\left(k\norm{e^k}^2 + (k-1)\norm{e^{k-1}}^2 - \frac{2k-1}{2}\left(\norm{e^k}^2 + \norm{e^{k-1}}^2\right)\right) + \inprod{y^k}{(k-1)r^{k-1} - k r^k} \\
		 = &\; \frac{1}{2\sigma_k}\norm{e^k}^2 - \frac{1}{2\sigma_k}\norm{e^{k-1}}^2 + \inprod{y^k}{(k-1)r^{k-1} - k r^k} \\
		 \geq &\; \frac{1}{2\sigma_k}\norm{e^k}^2 - \frac{1}{2\sigma_{k-1}}\norm{e^{k-1}}^2 + \inprod{y^k}{(k-1)r^{k-1} - k r^k},
	\end{aligned} 
\end{equation}

where in the last inequality, we use the fact that $\sigma_k \geq \sigma_{k-1} > 0$ for all $k\geq 1$. By summing the inequality in \eqref{eq-thm-iPGM-3} for $k=1,\dots,k$, we get (recall that $\norm{y^k}\leq M$ for all $k\geq 0$)
\begin{equation*}
\begin{aligned}
		-k \inprod{C}{X^k - \Xstar} \geq &\; \frac{1}{2\sigma_k}\norm{e^k}^2 - \frac{1}{2\sigma_0}\norm{e_0}^2 + \sum_{i=1}^k\inprod{y^i}{(i-1)r^{i-1} - i r^i} \\
		\geq &\; \frac{1}{2\sigma_k}\norm{e^k}^2 - \frac{1}{2\sigma_0}\norm{e_0}^2 - 2M\sum_{i=1}^k i\varepsilon_i.
	\end{aligned}	
\end{equation*}

The above inequality leads to the following upper bound on $\inprod{C}{X^k - \Xstar}$:
\begin{equation}
\label{eq-thm-iPGM-4}
\inprod{C}{X^k - \Xstar} \leq \frac{1}{k}\left(\frac{1}{2\sigma_0}\norm{e^0}^2 + 2M\sum_{i=1}^k i\varepsilon_i\right).	
\end{equation}

As a consequence, because $X^k \in \calF_k$ and $\inprod{C}{X^k} \geq \inprod{C}{\Xstar_k}$, it holds that 
\begin{equation}
\label{eq-thm-iPGM-5}
	\inprod{C}{X^k - \Xstar} \geq \inprod{C}{\Xstar_k - \Xstar} \geq -\norm{\ystar}\varepsilon_k = -\frac{\norm{\ystar}k\varepsilon_k}{k}.	
\end{equation}
Combining \eqref{eq-thm-iPGM-4} and \eqref{eq-thm-iPGM-5}, we see that 
\[
	-\frac{\norm{\ystar}k\varepsilon_k}{k} \leq \inprod{C}{X^k - \Xstar} \leq  \frac{1}{k}\left(\frac{1}{2\sigma_0}\norm{e^0}^2 + 2M\sum_{i=1}^k i\varepsilon_i\right).
\]

\begin{lemma}
\label{lemma-fk}
	Under the inexactness conditions in \eqref{eq-iPGM-inexact-conditions}, for any $X\in \mathbb{S}_+^n$, it holds that
	\[
		\inprod{C}{X - X^k} \geq \frac{1}{\sigma_k}\norm{X^{k} - X^{k-1}}^2 + \frac{1}{\sigma_k}\inprod{X^{k-1} - X}{X^{k} - X^{k-1}} + \inprod{\mathcal{A}^*y^k}{X - X^k}.
	\]
\end{lemma}
